# Save the transform function
def transform(grid):
    """Transform by zeroing out the smallest connected component of non-zero cells."""
    if len(grid) == 0:
        return grid

    visited = set()
    components = []

    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] != 0 and (i, j) not in visited:
                component = []
                stack = [(i, j)]
                while stack:
                    ci, cj = stack.pop()
                    if (ci, cj) in visited:
                        continue
                    visited.add((ci, cj))
                    component.append((ci, cj))
                    for di, dj in [(-1,0), (1,0), (0,-1), (0,1)]:
                        ni, nj = ci + di, cj + dj
                        if 0 <= ni < len(grid) and 0 <= nj < len(grid[0]):
                            if grid[ni][nj] != 0 and (ni, nj) not in visited:
                                stack.append((ni, nj))
                components.append(component)

    if not components:
        return grid

    min_comp_idx = min(range(len(components)), key=lambda i: len(components[i]))
    output = [row[:] for row in grid]
    for (i, j) in components[min_comp_idx]:
        output[i][j] = 0
    return output

