# Function to extract a grid block
def extract_grid_block(text, marker):
    """Extract 15x15 grid after marker."""
    pos = text.find(marker)
    if pos == -1:
        return []

    # Start after marker
    start = pos + len(marker)
    # Find end (next dictionary key or similar)
    # Look for pattern that ends grid section
    grid_text = text[start:start+10000]

    # Extract numeric rows
    rows = []
    current_row = []

    i = 0
    while i < len(grid_text):
        c = grid_text[i]
        if c.isdigit():
            current_row.append(int(c))
        elif c.isspace():
            # End of a number - trim spaces
            while i < len(grid_text) and grid_text[i].isspace():
                i += 1
            # If we have 15 values, save the row
            if len(current_row) == 15:
                rows.append(current_row)
                current_row = []
        else:
            # Non-numeric, non-space - check if it's a new section
            if i == 0 or i < len(grid_text):
                if current_row and len(current_row) == 15:
                    rows.append(current_row)
                    current_row = []
            while i < len(grid_text) and not grid_text[i].isdigit() and not grid_text[i].isspace():
                i += 1

    # Trim to 15 rows
    return rows[:15] if len(rows) >= 15 else rows[:15]

